1	package posemap
2	
3	import (
4		"errors"
5		"fmt"
6		"math"
7		"sort"
8		"sync"
9	)
10	
11	// Map 是一份带持久化文件的二维轨迹与路标地图。零值不可用，须经 Create
12	// 或 Open 得到。单个 Map 可被多个 goroutine 并发使用。
13	type Map struct {
14		mu     sync.Mutex
15		path   string
16		state  *mapState
17		closed bool
18	}
19	
20	// mapState 是地图的全部内存状态。
21	type mapState struct {
22		config      Config
23		trajectory  []Pose // 按时间严格递增；trajectory[0] 为初始位姿
24		landmarks   map[string]*landmarkState
25		segments    map[string]*segmentRecord
26		sources     []*frameSource // sources[k] 对应 trajectory[k+1]；长度恒为 len(trajectory)-1
27		corrections []*CorrectionRecord
28		corrIndex   map[string]string // 校正标识 -> 首次内容指纹
29	}
30	
31	// frameSource 是生成某一帧的原始输入，供回环校正重放路标观测与累计
32	// 原运动方差。该切片中的 nil 元素表示对应帧来自不携带逐帧依据的旧
33	// 文件，涉及它的历史范围不能校正。
34	type frameSource struct {
35		moveVariance float64
36		observations []Observation
37	}
38	
39	// landmarkState 是路标在地图坐标下的聚合状态。
40	//
41	// legacy* 只用于打开不携带逐帧观测来源的旧文件：旧文件中每一帧的观测
42	// 无法重放，因此旧文件里该路标的全部观测贡献视为固定的 legacyCount 次
43	// 平均，不随后续校正改变；旧文件之后新导入且依据完整的观测再做增量
44	// 平均。由本版本创建/导入的路标 legacyCount 为 0，全部观测均可重放。
45	type landmarkState struct {
46		x           float64
47		y           float64
48		count       int
49		legacyCount int
50		legacyMX    float64
51		legacyMY    float64
52	}
53	
54	// segmentRecord 记录一个已成功保存的段：内容指纹与首次导入结果，
55	// 供相同内容重复导入时直接返回。
56	type segmentRecord struct {
57		hash   string
58		result ImportResult
59	}
60	
61	// ImportResult 是一次成功段导入的结果：本段末位姿及方差，以及本段
62	// 涉及（观测到）的全部路标标识（去重、按标识排序）。
63	type ImportResult struct {
64		EndPose     Pose
65		LandmarkIDs []string
66	}
67	
68	// Create 在 path 处创建一份新地图并写入初始文件。path 已存在时返回
69	// 错误，以免覆盖既有数据（既有地图请用 Open）。
70	func Create(path string, cfg Config) (*Map, error) {
71		if err := validateConfig(cfg); err != nil {
72			return nil, err
73		}
74		st := &mapState{
75			config:     cfg,
76			trajectory: []Pose{{Time: cfg.InitialTime, X: cfg.InitialX, Y: cfg.InitialY, Heading: cfg.InitialHeading, Variance: cfg.InitialVariance}},
77			landmarks:  make(map[string]*landmarkState),
78			segments:   make(map[string]*segmentRecord),
79			corrIndex:  make(map[string]string),
80		}
81		m := &Map{path: path, state: st}
82		// O_EXCL：目标已存在即失败，绝不当作新地图覆盖。
83		if err := m.saveExclusive(); err != nil {
84			return nil, err
85		}
86		return m, nil
87	}
88	
89	// Open 打开 path 处由 Create/导入生成的地图文件。文件不存在时返回
90	// 包装了 fs.ErrNotExist 的错误；文件损坏返回可 errors.Is(ErrCorrupt)
91	// 的错误；格式版本不支持返回 ErrUnsupportedVersion。Open 绝不覆盖
92	// 无法识别的文件。
93	func Open(path string) (*Map, error) {
94		st, err := loadFile(path)
95		if err != nil {
96			return nil, err
97		}
98		return &Map{path: path, state: st}, nil
99	}
100	
101	// Path 返回地图对应的本地数据文件路径。
102	func (m *Map) Path() string {
103		m.mu.Lock()
104		defer m.mu.Unlock()
105		return m.path
106	}
107	
108	// Close 关闭地图。每次成功导入都已落盘，Close 本身不修改数据文件；
109	// 关闭后再调用其他方法返回 ErrClosed。
110	func (m *Map) Close() error {
111		m.mu.Lock()
112		defer m.mu.Unlock()
113		m.closed = true
114		return nil
115	}
116	
117	func validateConfig(cfg Config) error {
118		switch {
119		case !isFinite(cfg.InitialX) || !isFinite(cfg.InitialY) || !isFinite(cfg.InitialHeading):
120			return fmt.Errorf("%w: non-finite initial pose", ErrInvalidConfig)
121		case !isFinite(cfg.InitialVariance) || cfg.InitialVariance < 0:
122			return fmt.Errorf("%w: initial variance must be non-negative and finite", ErrInvalidConfig)
123		case cfg.MaxInterval <= 0:
124			return fmt.Errorf("%w: max interval must be positive", ErrInvalidConfig)
125		case !isFinite(cfg.MergeDistance) || cfg.MergeDistance <= 0:
126			return fmt.Errorf("%w: merge distance must be positive and finite", ErrInvalidConfig)
127		default:
128			return nil
129		}
130	}
131	
132	// ImportSegment 导入一批带非空段标识的有序帧。
133	//
134	// 整段要么全部生效（含落盘），要么因可区分的 *RejectError 被整段拒绝，
135	// 此前已提交的位姿、路标、观测次数不受影响。已成功保存的段标识再次以
136	// 相同内容导入时，直接返回首次导入的结果且不改变当前数据；同一标识
137	// 对应不同内容则以 RejectDuplicateMismatch 拒绝。
138	func (m *Map) ImportSegment(seg Segment) (ImportResult, error) {
139		m.mu.Lock()
140		defer m.mu.Unlock()
141		if m.closed {
142			return ImportResult{}, ErrClosed
143		}
144		st := m.state
145	
146		if seg.ID == "" {
147			return ImportResult{}, &RejectError{Kind: RejectEmptyID}
148		}
149		if len(seg.Frames) == 0 {
150			return ImportResult{}, &RejectError{Kind: RejectEmptySegment}
151		}
152	
153		// 已保存段：相同内容直接返回首次结果；不同内容明确拒绝。
154		// 不做任何校验或状态变更，即使其后又导入过其他段。
155		if rec, ok := st.segments[seg.ID]; ok {
156			if canonicalHash(seg.Frames) == rec.hash {
157				return cloneResult(rec.result), nil
158			}
159			return ImportResult{}, &RejectError{Kind: RejectDuplicateMismatch, Landmark: seg.ID, HasLandmark: true}
160		}
161	
162		// ---- 在暂存区上校验并推演，真实状态此时保持不变 ----
163		cur := st.trajectory[len(st.trajectory)-1]
164		prevTime := cur.Time
165		newPoses := make([]Pose, 0, len(seg.Frames))
166		staged := make(map[string]*landmarkState) // 本段触及路标的暂存聚合
167		touched := make(map[string]struct{})
168	
169		reject := func(kind string, frame int) (ImportResult, error) {
170			return ImportResult{}, &RejectError{Kind: kind, Frame: frame, HasFrame: true}
171		}
172	
173		for i, f := range seg.Frames {
174			// 时间：严格递增；首帧必须晚于初始时间或上一段末帧。
175			if f.Time <= prevTime {
176				return reject(RejectTimeOrder, i)
177			}
178			// 相邻位姿间隔上限。
179			if f.Time-prevTime > m.state.config.MaxInterval {
180				return reject(RejectInterval, i)
181			}
182			// 运动数值有限、方差非负。
183			if !isFinite(f.DX) || !isFinite(f.DY) || !isFinite(f.DHeading) || !isFinite(f.MoveVariance) {
184				return reject(RejectNonFinite, i)
185			}
186			if f.MoveVariance < 0 {
187				return reject(RejectNegativeVariance, i)
188			}
189			// 观测标识非空、观测位置有限。
190			for _, ob := range f.Observations {
191				if ob.ID == "" {
192					return reject(RejectEmptyID, i)
193				}
194				if !isFinite(ob.X) || !isFinite(ob.Y) {
195					return ImportResult{}, &RejectError{Kind: RejectNonFinite, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
196				}
197			}
198	
199			// 运动：先按运动前朝向把平移转换到地图坐标，再更新朝向并归一。
200			nx, ny := localToMap(cur.X, cur.Y, cur.Heading, f.DX, f.DY)
201			cur = Pose{
202				Time:     f.Time,
203				X:        nx,
204				Y:        ny,
205				Heading:  normalizeAngle(cur.Heading + f.DHeading),
206				Variance: cur.Variance + f.MoveVariance,
207			}
208			newPoses = append(newPoses, cur)
209	
210			// 观测按运动完成后的位姿转换到地图坐标，同帧按输入次序处理。
211			for _, ob := range f.Observations {
212				mx, my := localToMap(cur.X, cur.Y, cur.Heading, ob.X, ob.Y)
213				lm := staged[ob.ID]
214				if lm == nil {
215					lm = st.landmarks[ob.ID]
216					if lm != nil {
217						// 复制已提交路标，避免提前修改真实状态。
218						cp := *lm
219						lm = &cp
220					}
221				}
222				if lm != nil {
223					if math.Hypot(mx-lm.x, my-lm.y) > m.state.config.MergeDistance {
224						return ImportResult{}, &RejectError{Kind: RejectLandmarkConflict, Frame: i, HasFrame: true, Landmark: ob.ID, HasLandmark: true}
225					}
226					lm.x = (lm.x*float64(lm.count) + mx) / float64(lm.count+1)
227					lm.y = (lm.y*float64(lm.count) + my) / float64(lm.count+1)
228					lm.count++
229				} else {
230					lm = &landmarkState{x: mx, y: my, count: 1}
231				}
232				staged[ob.ID] = lm
233				touched[ob.ID] = struct{}{}
234			}
235	
236			prevTime = f.Time
237		}
238	
239		ids := make([]string, 0, len(touched))
240		for id := range touched {
241			ids = append(ids, id)
242		}
243		sort.Strings(ids)
244		res := ImportResult{EndPose: cur, LandmarkIDs: ids}
245	
246		// 逐帧依据（原运动方差与原始观测）与位姿一一对应，供以后的回环
247		// 校正重放。
248		newSources := make([]*frameSource, len(seg.Frames))
249		for i, f := range seg.Frames {
250			obs := append([]Observation(nil), f.Observations...)
251			newSources[i] = &frameSource{moveVariance: f.MoveVariance, observations: obs}
252		}
253	
254		// ---- 全部校验通过：提交内存状态并落盘；落盘失败精确回滚 ----
255		trajLenBefore := len(st.trajectory)
256		srcLenBefore := len(st.sources)
257		type undoLandmark struct {
258			lm *landmarkState
259			ok bool
260		}
261		undo := make(map[string]undoLandmark, len(staged))
262		for id, nl := range staged {
263			old, ok := st.landmarks[id]
264			undo[id] = undoLandmark{old, ok}
265			st.landmarks[id] = nl
266		}
267		st.trajectory = append(st.trajectory, newPoses...)
268		st.sources = append(st.sources, newSources...)
269		st.segments[seg.ID] = &segmentRecord{hash: canonicalHash(seg.Frames), result: cloneResult(res)}
270	
271		if err := m.saveReplace(); err != nil {
272			st.trajectory = st.trajectory[:trajLenBefore]
273			st.sources = st.sources[:srcLenBefore]
274			for id, u := range undo {
275				if u.ok {
276					st.landmarks[id] = u.lm
277				} else {
278					delete(st.landmarks, id)
279				}
280			}
281			delete(st.segments, seg.ID)
282			return ImportResult{}, err
283		}
284		return res, nil
285	}
286	
287	func cloneResult(r ImportResult) ImportResult {
288		ids := make([]string, len(r.LandmarkIDs))
289		copy(ids, r.LandmarkIDs)
290		r.LandmarkIDs = ids
291		return r
292	}
293	
294	// CurrentPose 返回当前位姿及其位置方差；尚无帧导入时返回初始位姿。
295	func (m *Map) CurrentPose() (Pose, error) {
296		m.mu.Lock()
297		defer m.mu.Unlock()
298		if m.closed {
299			return Pose{}, ErrClosed
300		}
301		return m.state.trajectory[len(m.state.trajectory)-1], nil
302	}
303	
304	// PoseAt 返回不晚于 t 的最后一份历史位姿及其方差。t 早于初始时间时
305	// 返回 ErrNotFound。
306	func (m *Map) PoseAt(t int64) (Pose, error) {
307		m.mu.Lock()
308		defer m.mu.Unlock()
309		if m.closed {
310			return Pose{}, ErrClosed
311		}
312		tr := m.state.trajectory
313		// j 为第一个时间 > t 的位置。
314		j := sort.Search(len(tr), func(j int) bool { return tr[j].Time > t })
315		if j == 0 {
316			return Pose{}, ErrNotFound
317		}
318		return tr[j-1], nil
319	}
320	
321	// Rect 描述一个包含边界的轴对齐矩形查询区域，单位米。
322	type Rect struct {
323		MinX, MinY, MaxX, MaxY float64
324	}
325	
326	// LandmarksInRect 返回矩形（含边界）内的路标及观测次数，按标识排序；
327	// 区域为空时返回非 nil 的空切片。上下界颠倒或含非有限值时报 ErrInvalidRect。
328	func (m *Map) LandmarksInRect(r Rect) ([]Landmark, error) {
329		m.mu.Lock()
330		defer m.mu.Unlock()
331		if m.closed {
332			return nil, ErrClosed
333		}
334		if !isFinite(r.MinX) || !isFinite(r.MinY) || !isFinite(r.MaxX) || !isFinite(r.MaxY) ||
335			r.MinX > r.MaxX || r.MinY > r.MaxY {
336			return nil, fmt.Errorf("%w: min bounds must not exceed max bounds and all values must be finite", ErrInvalidRect)
337		}
338		var out []Landmark
339		for id, lm := range m.state.landmarks {
340			if lm.x >= r.MinX && lm.x <= r.MaxX && lm.y >= r.MinY && lm.y <= r.MaxY {
341				out = append(out, Landmark{ID: id, X: lm.x, Y: lm.y, Count: lm.count})
342			}
343		}
344		sort.Slice(out, func(i, j int) bool { return out[i].ID < out[j].ID })
345		if out == nil {
346			out = []Landmark{}
347		}
348		return out, nil
349	}
350	
351	// AsRejectError 返回错误对应的 *RejectError；不是段拒绝错误时返回 nil、false。
352	func AsRejectError(err error) (*RejectError, bool) {
353		var r *RejectError
354		if errors.As(err, &r) {
355			return r, true
356		}
357		return nil, false
358	}
