270		}
271		lms, _ := m.LandmarksInRect(Rect{MinX: -1e9, MinY: -1e9, MaxX: 1e9, MaxY: 1e9})
272		if len(lms) != 2 {
273			t.Fatalf("landmark count = %d after duplicate import", len(lms))
