440		if err := m.Close(); err != nil {
441			t.Fatal(err)
442		}
443	
444		m2, err := Open(path)
445		if err != nil {
446			t.Fatalf("open legacy: %v", err)
447		}
448		defer m2.Close()
449	
450		// 旧文件可正常打开、查询。
451		p, err := m2.PoseAt(100)
452		if err != nil || p.X != 1 {
