	h := newHash()
	put := func(p []byte) { h.Write(p) }
	binary.BigEndian.PutUint32(b[:], uint32(len(sorted)))
	put(b[:])
	for _, s := range sorted {
		binary.BigEndian.PutUint32(b[:], uint32(len(s)))
		put(b[:])
		put([]byte(s))
	}
	return sumHashString(h)
}

