	h.Write(lenBuf[:])
	for _, s := range sorted {
		binary.BigEndian.PutUint32(lenBuf[:], uint32(len(s)))
		h.Write(lenBuf[:])
		h.Write([]byte(s))
	}
	return fmt.Sprintf("%x", h.Sum(nil))
}

