		count int
		x, y  float64
	}
	aggs := make(map[occKey]*agg, len(affectedKeys))
	for _, k := range affectedKeys {
		occ := st.landmarks[k.id].appearances[k.num-1]
		a := &agg{}
		if occ.legacyCount > 0 {
			a.count = occ.legacyCount
			a.x = occ.legacyMX
			a.y = occ.legacyMY
		}
		aggs[k] = a
	}
	for j := 1; j <= end; j++ {
