	// 同标识、同原因、同集合（次序相反）：返回首次结果。
	again, err := m.Invalidate(Invalidation{ID: "op", Reason: "r", Landmarks: []string{"M", "L"}})
	if err != nil || len(again.Landmarks) != 2 {
